def data_generation():
    """Silme sırasında başlayan geç yanıtların veriyi geri getirmesini önler."""
    with DATA_WRITE_LOCK:
        return DATA_GENERATION

def bump_data_generation():
    global DATA_GENERATION
    with DATA_WRITE_LOCK:
        DATA_GENERATION += 1
        return DATA_GENERATION


@contextmanager
def maintenance_window():
    """Pause sync and serialize destructive database replacement/deletion."""
    if not MAINTENANCE_LOCK.acquire(blocking=False):
        raise RequestInputError(
            "Divan bakım işlemi zaten sürüyor; biraz sonra yeniden deneyin.",
            409)
    MAINTENANCE_ACTIVE.set()
    try:
        sync_service.reset_runtime_state()
        with DATA_WRITE_LOCK:
            yield
    finally:
        MAINTENANCE_ACTIVE.clear()
        MAINTENANCE_LOCK.release()

def conversation_is_live(c, conv_id):
    return bool(c.execute("SELECT 1 FROM conversations WHERE id=?",
                          (conv_id,)).fetchone())

def conversation_is_open(c, conv_id):
    return bool(c.execute(
        "SELECT 1 FROM conversations WHERE id=? AND ended=0 "
        "AND archived_at IS NULL",
        (conv_id,)).fetchone())

