ALL_MASTERS = dict(THERAPISTS)
ALL_MASTERS.update(PHILOSOPHERS)

def is_philosopher(master_id):
    return master_id in PHILOSOPHERS

def master_record(master_id, fallback=True):
    record = ALL_MASTERS.get(master_id)
    if record is None and fallback:
        return THERAPISTS["freud"]
    return record

def master_name(master_id):
    record = master_record(master_id, fallback=False)
    return record["name"] if record else str(master_id or "")

