def schema_strategy_record(strategy_id):
    return next((
        row for row in SCHEMA_STRATEGY_LIBRARY
        if row["id"] == strategy_id), None)


def public_schema_strategies(current_stage="", slot_key=""):
    output = []
    for row in SCHEMA_STRATEGY_LIBRARY:
        item = {
            key: (list(value) if isinstance(value, tuple) else value)
            for key, value in row.items()
        }
        item["relevant"] = bool(
            (current_stage and current_stage in row["stage_ids"])
            or (slot_key and (
                slot_key in row["slot_keys"]
                or ("custom" in row["slot_keys"]
                    and slot_key.startswith("custom_")))))
        output.append(item)
    return output


