THERAPY_VOICE_BORROWING_RULE = (
    "Kullanıcı açıkça karşılaştırma istemedikçe başka ekolün kavramını, "
    "soru biçimini veya müdahalesini ana çerçeveye taşıma."
)


def _build_therapy_voice_contract(
        analysis_unit, attention_order, change_mechanism, response_shape,
        question_policy, repair_style, closing_style,
        forbidden_borrowing):
    """Build one compact contract while preserving the shared lens boundary."""
    return {
        "analysis_unit": analysis_unit,
        "attention_order": attention_order,
        "change_mechanism": change_mechanism,
        "response_shape": response_shape,
        "question_policy": question_policy,
        "repair_style": repair_style,
        "closing_style": closing_style,
        "forbidden_borrowing": (
            THERAPY_VOICE_BORROWING_RULE + " " + forbidden_borrowing
        ),
    }


