def native_bootstrap_payload():
    """Build the stable, secret-free startup document for native clients."""
    provider_id, providers = public_provider_settings()
    provider = dict(providers[provider_id])
    provider["id"] = provider_id
    return {
        "api_contract_version": API_CONTRACT_VERSION,
        "app_version": VERSION,
        "capabilities": native_capabilities(),
        "provider": provider,
        "therapists": public_therapist_catalog(),
        "philosophers": public_philosopher_catalog(),
        "settings": {
            "context_window_tokens": context_window_tokens(),
            "context_window_options": list(CONTEXT_WINDOW_TOKEN_OPTIONS),
            "privacy_seen": get_setting("privacy_seen") == "1",
            "pin_set": bool(get_setting("pin_hash")),
            "retention_days": int(get_setting("retention_days") or 0),
            "simple_mode": get_setting("simple_mode") == "1",
            "credential_storage": SECRET_STORE_KIND,
        },
    }

def pin_hash(pin, salt=None):
    salt = salt or os.urandom(16).hex()
    digest = hashlib.pbkdf2_hmac("sha256", pin.encode("utf-8"),
                                 bytes.fromhex(salt), 180000).hex()
    return salt + ":" + digest

def pin_matches(pin, stored):
    try:
        salt = stored.split(":", 1)[0]
        return hmac.compare_digest(pin_hash(pin, salt), stored)
    except Exception:
        return False

def reset_app_unlock_state():
    """Forget every in-memory unlock and rate-limit record."""
    with APP_UNLOCK_LOCK:
        APP_UNLOCK_SESSIONS.clear()
        APP_UNLOCK_FAILURES.clear()

def unlock_cookie_token(raw_cookie):
    try:
        cookie = SimpleCookie()
        cookie.load(raw_cookie or "")
        morsel = cookie.get(APP_UNLOCK_COOKIE)
    except CookieError:
        morsel = None
    return morsel.value if morsel else ""

def app_unlock_fingerprint(stored_pin=None):
    stored_pin = stored_pin if stored_pin is not None else get_setting("pin_hash")
    return hashlib.sha256(str(stored_pin or "").encode("utf-8")).hexdigest()

def prune_app_unlock_state(stamp=None):
    stamp = time.time() if stamp is None else stamp
    with APP_UNLOCK_LOCK:
        for token, record in list(APP_UNLOCK_SESSIONS.items()):
            if record[0] <= stamp:
                APP_UNLOCK_SESSIONS.pop(token, None)
        for client, record in list(APP_UNLOCK_FAILURES.items()):
            if stamp - record.get("first", stamp) > (
                    APP_UNLOCK_FAILURE_WINDOW_SECONDS +
                    APP_UNLOCK_BLOCK_SECONDS):
                APP_UNLOCK_FAILURES.pop(client, None)

def app_unlock_valid(raw_cookie, stored_pin=None):
    stored_pin = stored_pin if stored_pin is not None else get_setting("pin_hash")
    if not stored_pin:
        return True
    token = unlock_cookie_token(raw_cookie)
    if not token:
        return False
    stamp = time.time()
    fingerprint = app_unlock_fingerprint(stored_pin)
    with APP_UNLOCK_LOCK:
        record = APP_UNLOCK_SESSIONS.get(token)
        if not record or record[0] <= stamp or not hmac.compare_digest(
                record[1], fingerprint):
            APP_UNLOCK_SESSIONS.pop(token, None)
            return False
        # Active use extends the local app session without changing the cookie.
        APP_UNLOCK_SESSIONS[token] = (
            stamp + APP_UNLOCK_TTL_SECONDS, fingerprint)
    return True

def issue_app_unlock_cookie(stored_pin=None):
    stored_pin = stored_pin if stored_pin is not None else get_setting("pin_hash")
    token = base64.urlsafe_b64encode(os.urandom(32)).decode("ascii").rstrip("=")
    with APP_UNLOCK_LOCK:
        APP_UNLOCK_SESSIONS[token] = (
            time.time() + APP_UNLOCK_TTL_SECONDS,
            app_unlock_fingerprint(stored_pin),
        )
    cookie = SimpleCookie()
    cookie[APP_UNLOCK_COOKIE] = token
    morsel = cookie[APP_UNLOCK_COOKIE]
    morsel["path"] = "/"
    morsel["httponly"] = True
    morsel["samesite"] = "Strict"
    morsel["max-age"] = str(APP_UNLOCK_TTL_SECONDS)
    return morsel.OutputString()

def expire_app_unlock_cookie():
    cookie = SimpleCookie()
    cookie[APP_UNLOCK_COOKIE] = ""
    morsel = cookie[APP_UNLOCK_COOKIE]
    morsel["path"] = "/"
    morsel["httponly"] = True
    morsel["samesite"] = "Strict"
    morsel["max-age"] = "0"
    return morsel.OutputString()

def app_unlock_rate_status(client, stamp=None):
    stamp = time.time() if stamp is None else stamp
    prune_app_unlock_state(stamp)
    with APP_UNLOCK_LOCK:
        record = APP_UNLOCK_FAILURES.get(client)
        if not record:
            return 0
        blocked_until = float(record.get("blocked_until") or 0)
        return max(0, int(math.ceil(blocked_until - stamp)))

def record_app_unlock_failure(client, stamp=None):
    stamp = time.time() if stamp is None else stamp
    with APP_UNLOCK_LOCK:
        record = APP_UNLOCK_FAILURES.get(client)
        if (not record or stamp - record.get("first", stamp) >
                APP_UNLOCK_FAILURE_WINDOW_SECONDS):
            record = {"first": stamp, "count": 0, "blocked_until": 0}
        record["count"] += 1
        if record["count"] >= APP_UNLOCK_MAX_FAILURES:
            record["blocked_until"] = stamp + APP_UNLOCK_BLOCK_SECONDS
        APP_UNLOCK_FAILURES[client] = record
        return max(0, int(math.ceil(record["blocked_until"] - stamp)))

def clear_app_unlock_failures(client):
    with APP_UNLOCK_LOCK:
        APP_UNLOCK_FAILURES.pop(client, None)

