def _safety_fold(text):
    translated = str(text or "").translate(SAFETY_TURKISH_TRANSLATION)
    folded = unicodedata.normalize("NFKD", translated).encode(
        "ascii", "ignore").decode("ascii").casefold()
    return " " + re.sub(r"\s+", " ", folded).strip() + " "


def _safety_clearly_nonliteral(folded):
    """Suppress a *single clause* only when its meaning is clearly non-current.

    A current-time word must not cancel an explicit negation ("şu anda ...
    istemiyorum").  Callers split adversative/mixed sentences first so a safe
    clause cannot suppress a separate current-risk clause.
    """
    negative_life_wish = any(phrase in folded for phrase in (
        "yasamak istemiyorum", "uyanmak istemiyorum"))
    if (not negative_life_wish and
            any(marker in folded for marker in SAFETY_NEGATION_MARKERS)):
        return True
    if any(marker in folded for marker in SAFETY_CURRENT_SAFE_MARKERS):
        return True
    current = any(marker in folded for marker in SAFETY_CURRENT_RISK_MARKERS)
    historical = any(
        marker in folded for marker in SAFETY_PAST_CONTEXT_MARKERS)
    if historical and not current:
        return True
    fiction_hits = sum(
        1 for marker in SAFETY_FICTION_MARKERS if marker in folded)
    return fiction_hits >= 2 and not current


def _safety_clauses(text):
    """Return padded, folded clauses without losing quoted-person context."""
    folded = _safety_fold(text).strip()
    if not folded:
        return []
    clauses = []
    for part in SAFETY_CLAUSE_SPLIT_RE.split(folded):
        part = re.sub(r"\s+", " ", part).strip(" \t\r\n\"'“”‘’")
        if part:
            clauses.append(" " + part + " ")
    return clauses or [" " + folded + " "]


def _safety_clause_decision(folded, context="conversation"):
    """Classify one grammatical clause; never infer a diagnosis or severity."""
    result = {
        "detected": False, "kind": "", "message": "",
        "context": str(context or "conversation"),
        "detector_version": SAFETY_DETECTOR_VERSION,
    }
    if _safety_clearly_nonliteral(folded):
        return result

    explicit_violence = (
        any(term in folded for term in SAFETY_OTHER_HARM_TERMS) or
        any(pattern.search(folded)
            for pattern in SAFETY_VIOLENCE_PATTERNS))
    if explicit_violence:
        return {
            **result, "detected": True, "kind": "harm_to_others",
            "message": VIOLENCE_HELP_MESSAGE,
        }

    direct_self = (
        any(term in folded for term in SAFETY_DIRECT_SELF_TERMS) or
        any(pattern.search(folded)
            for pattern in SAFETY_DIRECT_SELF_METHOD_PATTERNS))
    self_marker = any(term in folded for term in SAFETY_SELF_MARKERS)
    harm_term = any(term in folded for term in SAFETY_SELF_HARM_TERMS)
    intent = any(term in folded for term in SAFETY_INTENT_MARKERS)
    academic = any(term in folded for term in SAFETY_ACADEMIC_MARKERS)
    other_person = any(
        marker in folded for marker in SAFETY_OTHER_PERSON_MARKERS)
    reported_speech = any(marker in folded for marker in (
        " diyor", " dedi", " soyluyor", " soyledi",
        " edecegini", " yapacagini", " acagini", " ecegini"))
    dream_context = (
        str(context or "") == "dream_analysis" and
        any(term in folded for term in (
            "ruya", "ruyamda", "ruyada", "dusumde", "kabusumda")) and
        not any(term in folded for term in (
            "uyandigimda da", "gercekte de", "hala", "su anda", "simdi")))

    if (other_person and harm_term and intent
            and (not direct_self or reported_speech)):
        return {
            **result, "detected": True, "kind": "other_person_self_harm",
            "message": OTHER_PERSON_CRISIS_HELP_MESSAGE,
        }
    if (direct_self or
            (self_marker and harm_term and intent and not academic)):
        if dream_context:
            return result
        return {
            **result, "detected": True, "kind": "self_harm",
            "message": CRISIS_HELP_MESSAGE,
        }
    if other_person and harm_term and intent:
        return {
            **result, "detected": True, "kind": "other_person_self_harm",
            "message": OTHER_PERSON_CRISIS_HELP_MESSAGE,
        }
    return result


def user_text_safety_gate(text, context="conversation"):
    """Return a deterministic safety decision for user-authored model input.

    Bare topic words (for example an academic question about suicide) are not
    enough. Direct first-person intent remains model-independent. Historical
    dream analysis is treated as contextual unless the text also says the risk
    continues now.
    """
    result = {
        "detected": False, "kind": "", "message": "",
        "context": str(context or "conversation"),
        "detector_version": SAFETY_DETECTOR_VERSION,
    }
    clauses = _safety_clauses(text)
    if not clauses:
        return result

    previous_harm_clause = ""
    for index, clause in enumerate(clauses):
        decision = _safety_clause_decision(clause, context)
        if decision["detected"]:
            decision["clause_index"] = index
            return decision
        has_harm_topic = any(
            term in clause for term in SAFETY_SELF_HARM_TERMS)
        if has_harm_topic:
            previous_harm_clause = clause
            continue
        # "Dün ... düşünüyordum ama şimdi yine istiyorum" gibi ikinci
        # cümlecikte özne/eylem düşebilir. Yalnız açık güncellik + niyet varsa
        # hemen önceki zarar konusunu devral; güvenli güncellik bunu bastırır.
        if (previous_harm_clause
                and any(marker in clause
                        for marker in SAFETY_CURRENT_RISK_MARKERS)
                and any(marker in clause for marker in SAFETY_INTENT_MARKERS)
                and not _safety_clearly_nonliteral(clause)):
            inherited = _safety_clause_decision(
                previous_harm_clause + clause.strip() + " ", context)
            if inherited["detected"]:
                inherited["clause_index"] = index
                inherited["inherited_topic"] = True
                return inherited
    return result

def crisis_detected(text):
    return bool(user_text_safety_gate(text)["detected"])


def record_safety_event(connection, conv_id, safety, source_message=None,
                        detector_context=None):
    """Persist a hold reason separately from the reversible capability flag."""
    stamp = now()
    decision = safety or {}
    cursor = connection.execute(
        "INSERT INTO safety_events("
        "conv,source_message,kind,detector_context,detector_version,status,"
        "created) VALUES(?,?,?,?,?,'active',?)",
        (
            conv_id, source_message,
            str(decision.get("kind") or "unspecified")[:80],
            str(detector_context or decision.get("context") or
                "conversation")[:80],
            int(decision.get("detector_version") or
                SAFETY_DETECTOR_VERSION), stamp,
        ))
    connection.execute(
        "UPDATE conversations SET safety_hold=1,updated=? WHERE id=?",
        (stamp, conv_id))
    return cursor.lastrowid

# Modeller bazen persona içindeki ton tariflerini diyaloğa çevirmek yerine
# "Yavaşça, ... tartarak:" gibi bir sahne yönergesi olarak yazabiliyor.
# Kullanıcı doğrudan terapistin sözünü görmeli; anlatıcı sunuşunu değil.
STAGE_STARTERS = (
    "yavaşça", "bir an sessiz", "bir an dur", "bir an bekle",
    "derin bir nefes", "derin, neredeyse", "başımı", "başınızı",
    "sesim", "sesi ", "sesi,", "sesimi", "sesini", "dinliyorum",
    "sakin,", "sakin bir", "hafif bir", "hafif,", "hafifçe", "sessiz ", "gözlerim",
    "gözlerimi", "yumuşak,", "yumuşak bir", "odanın içinde",
    "yerimde", "duyulur bir nefes", "nefesimi",
)
STAGE_OPENING_RE = re.compile(
    r"^\s*\*{0,2}(?:Yavaşça|Bir an (?:sessiz|dur|bekle)|"
    r"Derin(?: bir nefes|, neredeyse)|Başımı|Başınızı|Sesim|Sesi[ ,]|"
    r"Sesimi|Sesini|Dinliyorum|Sakin,|Sakin bir|Hafif bir|Hafif,|Hafifçe|Sessiz |"
    r"Gözlerim|Gözlerimi|Yumuşak,|Yumuşak bir|Odanın içinde|Yerimde|"
    r"Duyulur bir nefes|Nefesimi)[\s\S]{0,600}?:\s*\*{0,2}\s*",
    re.IGNORECASE,
)
STAGE_ITALIC_RE = re.compile(
    r"^\s*\*((?:Duyulur bir nefes|Yavaşça|Bir an |Derin bir nefes|"
    r"Başımı|Sesim|Sesi[ ,]|Hafif|Sessiz )[\s\S]{0,500}?)\*\s*",
    re.IGNORECASE,
)

# Streaming must not hold a genuine reply for hundreds of characters merely
# because its first word resembles one of the blocked narrator openings.  The
# common unwanted openings fit comfortably below this guard and end in a
# colon; after the guard, preserving responsive text wins over speculative
# filtering.  The final persisted answer is still passed through
# ``strip_stage_opening`` in full.
STAGE_OPENING_STREAM_BUFFER_LIMIT = 128

# Fast local models may emit one or two characters per provider event.  Sending
# every event through HTTP and SwiftUI makes the visible reply appear in a late
# burst even though generation is progressing.  The first safe fragment is
# always emitted immediately; only subsequent fast fragments are coalesced.
CHAT_DELTA_BATCH_CHAR_LIMIT = 32
CHAT_DELTA_BATCH_SECONDS = 0.04

def strip_stage_opening(text):
    cleaned = STAGE_ITALIC_RE.sub("", text or "", count=1)
    return STAGE_OPENING_RE.sub("", cleaned, count=1).lstrip()

def stage_opening_candidate(text):
    probe = (text or "").lstrip(" \t\r\n*").casefold()
    if not probe:
        return True
    return any(s.startswith(probe) or probe.startswith(s)
               for s in STAGE_STARTERS)

def stage_opening_should_wait(text):
    """Whether an incremental prefix still needs narrator-opening buffering."""
    value = str(text or "")
    if not stage_opening_candidate(value):
        return False
    if len(value) >= STAGE_OPENING_STREAM_BUFFER_LIMIT:
        return False
    # Once a complete first line/sentence arrives without the colon required
    # by STAGE_OPENING_RE, it is ordinary user-visible prose.
    stripped = value.strip()
    if "\n" in value or (stripped and stripped[-1:] in ".!?"):
        return False
    return True

# --------------------------------------------------------- model sağlayıcıları

class ProviderError(RuntimeError):
    def __init__(self, code, message, retry_after=None):
        super().__init__(message)
        self.code = code
        self.retry_after = retry_after

class NoRedirectHandler(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None

def bounded_retry_after(value, wall_time=None):
    """Parse Retry-After seconds/HTTP-date without allowing huge sleeps."""
    raw = str(value or "").strip()
    if not raw:
        return None
    seconds = None
    try:
        seconds = float(raw)
    except (TypeError, ValueError):
        try:
            parsed = parsedate_to_datetime(raw)
            seconds = parsed.timestamp() - (
                time.time() if wall_time is None else float(wall_time))
        except (TypeError, ValueError, OverflowError):
            return None
    if not math.isfinite(seconds) or seconds <= 0:
        return None
    return max(1.0, min(
        float(CHAT_MAX_RETRY_AFTER_SECONDS), seconds))

def provider_error(exc, local=False):
    if isinstance(exc, ProviderError):
        return exc
    if isinstance(exc, urllib.error.HTTPError):
        error_type = ""
        error_code = ""
        error_message = ""
        try:
            raw = exc.read(256 * 1024)
            payload = json.loads(raw.decode("utf-8"))
            detail = payload.get("error", {}) if isinstance(
                payload, dict) else {}
            if isinstance(detail, dict):
                error_type = str(detail.get("type") or "").casefold()
                error_code = str(detail.get("code") or "").casefold()
                error_message = str(detail.get("message") or "").casefold()
        except (OSError, UnicodeDecodeError, ValueError, TypeError):
            pass
        permission_denied = (
            "insufficient permission" in error_message or
            "permission" in error_code or
            error_type in ("permission_error", "insufficient_permissions")
        )
        model_missing = (
            error_code in (
                "model_not_found", "invalid_model", "model_not_available",
                "model_not_loaded", "unknown_model")
            or error_type in (
                "model_not_found", "model_not_available",
                "model_not_loaded")
            or (
                "model" in error_message and any(
                    marker in error_message for marker in (
                        "model not exist", "model does not exist",
                        "model not found", "model is not loaded",
                        "model not loaded", "unknown model",
                        "invalid model id"))))
        if exc.code == 401 and not permission_denied:
            return ProviderError(
                "auth_failed", "API anahtarı kabul edilmedi.")
        if exc.code == 403 or permission_denied:
            return ProviderError(
                "insufficient_permissions",
                "API anahtarının bu işlem için gerekli izni yok.")
        if exc.code == 404:
            return ProviderError(
                "model_not_found", "Model veya sağlayıcı uç noktası bulunamadı.")
        if exc.code in (400, 422):
            if model_missing:
                return ProviderError(
                    "model_not_found",
                    "Seçili model sağlayıcıda bulunamadı veya yüklü değil.")
            return ProviderError(
                "invalid_provider_request",
                "Model sağlayıcısı bu isteği geçersiz buldu.")
        if exc.code == 429:
            if error_code in ("insufficient_quota", "billing_hard_limit_reached"):
                return ProviderError(
                    "quota_exhausted",
                    "Sağlayıcı bakiyesi veya kullanım kotası tükendi.")
            return ProviderError(
                "rate_limited", "Sağlayıcının kullanım sınırına ulaşıldı.",
                bounded_retry_after(
                    (exc.headers or {}).get("Retry-After")))
        if exc.code in (408, 504):
            return ProviderError(
                "provider_timeout",
                "Model sağlayıcısı zamanında yanıt vermedi.")
        return ProviderError(
            "provider_error", "Model sağlayıcısı isteği tamamlayamadı.")
    reason = exc.reason if isinstance(
        exc, urllib.error.URLError) else exc
    if isinstance(reason, (TimeoutError, socket.timeout)):
        return ProviderError(
            "provider_timeout",
            "Model sağlayıcısı zamanında yanıt vermedi.")
    if local:
        return ProviderError(
            "local_unavailable",
            "Yerel model sunucusuna ulaşılamadı. Sunucunun açık olduğunu denetleyin.")
    return ProviderError(
        "provider_unavailable", "Model sağlayıcısına bağlanılamadı.")

def open_provider_url(request, config,
                      timeout=ARTIFACT_PROVIDER_TIMEOUT_SECONDS):
    try:
        if config.get("local"):
            opener = urllib.request.build_opener(
                urllib.request.ProxyHandler({}), NoRedirectHandler())
            return opener.open(request, timeout=timeout)
        return urllib.request.urlopen(request, timeout=timeout)
    except Exception as exc:
        raise provider_error(exc, bool(config.get("local"))) from None

def read_limited(response, limit):
    body = response.read(limit + 1)
    if len(body) > limit:
        raise ProviderError(
            "response_too_large", "Model sağlayıcısının yanıtı çok büyük.")
    return body

def local_model_looks_chat_capable(model_id):
    """Exclude only obvious embedding/reranking/audio entries in auto mode."""
    folded = str(model_id or "").casefold().replace("_", "-")
    return not any(marker in folded
                   for marker in LOCAL_NON_CHAT_MODEL_MARKERS)

def discover_local_models(base_url=None, secret="", use_cache=True):
    base_url = normalize_local_base_url(base_url)
    cache_key = (base_url, bool(secret))
    with LOCAL_MODEL_CACHE_LOCK:
        cached = LOCAL_MODEL_CACHE.get(cache_key)
        if use_cache and cached and time.time() - cached[0] < 45:
            return list(cached[1])
    headers = {"Accept": "application/json"}
    secret = clean_secret(secret)
    if secret:
        headers["Authorization"] = "Bearer " + secret
    request = urllib.request.Request(
        base_url + "/models", headers=headers, method="GET")
    config = {"local": True}
    try:
        with open_provider_url(request, config, timeout=2.5) as response:
            raw = read_limited(response, 1024 * 1024)
        payload = json.loads(raw.decode("utf-8"))
    except ProviderError:
        raise
    except (UnicodeDecodeError, json.JSONDecodeError, TypeError):
        raise ProviderError(
            "invalid_local_response",
            "Yerel model sunucusu geçerli bir model listesi döndürmedi.") from None
    models, seen = [], set()
    for row in payload.get("data", []) if isinstance(payload, dict) else []:
        value = row.get("id") if isinstance(row, dict) else None
        try:
            value = clean_model_id(value)
        except ValueError:
            continue
        if not local_model_looks_chat_capable(value):
            continue
        if value not in seen:
            seen.add(value)
            models.append(value)
        if len(models) >= 200:
            break
    with LOCAL_MODEL_CACHE_LOCK:
        LOCAL_MODEL_CACHE[cache_key] = (time.time(), tuple(models))
    return models

def anthropic_messages(messages):
    systems, turns = [], []
    for item in messages or []:
        role = item.get("role")
        content = str(item.get("content") or "")
        if role == "system":
            if content:
                systems.append(content)
            continue
        if role not in ("user", "assistant") or not content:
            continue
        if turns and turns[-1]["role"] == role:
            turns[-1]["content"] += "\n\n" + content
        else:
            turns.append({"role": role, "content": content})
    if not turns:
        turns = [{"role": "user", "content": "Devam et."}]
    return "\n\n".join(systems), turns

def openai_response_input(messages):
    """Chat geçmişini Responses API'nin instructions + input yapısına çevir."""
    instructions, turns = [], []
    for item in messages or []:
        role = item.get("role")
        content = str(item.get("content") or "")
        if role in ("system", "developer"):
            if content:
                instructions.append(content)
            continue
        if role not in ("user", "assistant") or not content:
            continue
        turns.append({"role": role, "content": content})
    if not turns:
        turns = [{"role": "user", "content": "Devam et."}]
    return "\n\n".join(instructions), turns

def provider_request(payload, provider_id=None, model_id=None,
                     config_override=None):
    """Build a provider request, optionally pinning a durable job snapshot."""
    provider_id = provider_id or payload.get("_provider_id")
    model_id = model_id or payload.get("_model_id")
    # Somut bir yerel model snapshotı varken güncel ayardaki "auto" yüzünden
    # yeniden model keşfi yapma. Snapshot "auto" ise de sonradan değiştirilmiş
    # model ayarını kullanmak yerine bu sunucuda gerçekten yüklü modeli çöz.
    pinned_local = (
        config_override is None and provider_id == "lmstudio" and
        bool(model_id))
    config = (dict(config_override) if config_override is not None else
              provider_config(
                  provider=provider_id, resolve_local_model=not pinned_local))
    if pinned_local and model_id == "auto":
        models = discover_local_models(
            config["base_url"], config["secret"])
        if not models:
            raise ProviderError(
                "no_local_models",
                "Yerel sunucu açık fakat kullanılabilir model bulunamadı.")
        config = dict(config)
        config["model"] = models[0]
    elif model_id and model_id != "auto":
        config = dict(config)
        config["model"] = clean_model_id(
            model_id, allow_auto=config["id"] == "lmstudio")
    messages = payload.get("messages") or []
    max_tokens = int(payload.get("max_tokens") or MAX_TOKENS_NOTE)
    stream = bool(payload.get("stream"))
    headers = {"Content-Type": "application/json",
               "Accept": "text/event-stream" if stream else "application/json"}
    if config["protocol"] == "anthropic_messages":
        system, turns = anthropic_messages(messages)
        outgoing = {"model": config["model"], "messages": turns,
                    "max_tokens": max_tokens, "stream": stream}
        if system:
            outgoing["system"] = system
        headers["x-api-key"] = config["secret"]
        headers["anthropic-version"] = "2023-06-01"
    elif config["protocol"] == "openai_responses":
        instructions, turns = openai_response_input(messages)
        outgoing = {
            "model": config["model"],
            "input": turns,
            "max_output_tokens": max_tokens,
            "stream": stream,
            # Görüşmeler uygulamanın kendi SQLite hafızasında tutuluyor.
            # OpenAI tarafında Responses durum saklamasına ihtiyaç yok.
            "store": False,
        }
        if instructions:
            outgoing["instructions"] = instructions
        headers["Authorization"] = "Bearer " + config["secret"]
    else:
        outgoing = {"model": config["model"], "messages": messages,
                    "stream": stream}
        token_key = ("max_completion_tokens"
                     if config["id"] == "openai" else "max_tokens")
        outgoing[token_key] = max_tokens
        if config["secret"]:
            headers["Authorization"] = "Bearer " + config["secret"]
    request = urllib.request.Request(
        config["endpoint"], data=json.dumps(outgoing).encode("utf-8"),
        headers=headers, method="POST")
    request.divan_provider = config
    return request, config


def provider_test_config(data):
    """Validate unsaved Settings fields without persisting the credential."""
    provider = str(data.get("provider") or selected_provider()).strip().lower()
    if provider not in PROVIDERS:
        raise RequestInputError("model sağlayıcısı geçersiz")
    info = PROVIDERS[provider]
    raw_model = data.get("model")
    model = clean_model_id(
        raw_model if raw_model not in (None, "") else
        get_setting("{}_model".format(provider)) or info["default_model"],
        allow_auto=provider == "lmstudio")
    supplied_secret = data.get("api_key")
    secret = clean_secret(
        supplied_secret if supplied_secret not in (None, "")
        else provider_secret(provider))
    if info.get("key_required") and not secret:
        raise ProviderError(
            "missing_api_key",
            "{} API anahtarı gerekli.".format(info["label"]))
    result = {
        "id": provider,
        "label": info["label"],
        "protocol": info["protocol"],
        "model": model,
        "secret": secret,
        "local": bool(info.get("local")),
    }
    if provider == "lmstudio":
        result["base_url"] = normalize_local_base_url(
            data.get("base_url") or data.get("lmstudio_base_url") or
            get_setting("lmstudio_base_url") or info["default_base_url"])
        if model == "auto":
            models = discover_local_models(
                result["base_url"], secret, use_cache=False)
            if not models:
                raise ProviderError(
                    "no_local_models",
                    "Yerel sunucuda sohbet modeli bulunamadı.")
            result["model"] = models[0]
        result["endpoint"] = result["base_url"] + "/chat/completions"
    else:
        result["endpoint"] = info["endpoint"]
    return result


def test_provider_connection(data):
    config = provider_test_config(data)
    started = time.monotonic()
    request, config = provider_request({
        "messages": [
            {"role": "system", "content": (
                "Bu yalnızca bağlantı denetimidir. Kişisel veri isteme. ")},
            {"role": "user", "content": "Yalnız TAMAM yaz."},
        ],
        "max_tokens": 128,
        "stream": False,
    }, config_override=config)
    try:
        with open_provider_url(
                request, config,
                timeout=PROVIDER_TEST_TIMEOUT_SECONDS) as response:
            raw = read_limited(response, 2 * 1024 * 1024)
        payload = json.loads(raw.decode("utf-8"))
        if provider_completion_limit_reason(payload, config):
            raise ProviderError(
                "provider_output_truncated",
                "Model bağlantı denetimini tamamlayamadı.")
        answer = parse_provider_response(payload, config)
        if not str(answer or "").strip():
            raise ProviderError(
                "empty_provider_response",
                "Bağlantı kuruldu ancak model boş yanıt verdi.")
    except ProviderError:
        raise
    except (UnicodeDecodeError, json.JSONDecodeError, TypeError, KeyError):
        raise ProviderError(
            "invalid_provider_response",
            "Sağlayıcı geçerli bir model yanıtı döndürmedi.") from None
    return {
        "ok": True,
        "message": "Bağlantı ve model yanıtı doğrulandı.",
        "provider": config["id"],
        "model": config["model"],
        "latency_ms": max(0, int((time.monotonic() - started) * 1000)),
    }

def ds_request(payload):
    """Eski ad korunur; istek seçili sağlayıcıya uyarlanır."""
    request, _ = provider_request(payload)
    return request

def openai_response_text(data):
    """Ham Responses API JSON'undan bütün görünür metni sırayla çıkar."""
    if not isinstance(data, dict):
        return ""
    parts = []
    for item in data.get("output", []):
        if not isinstance(item, dict) or item.get("type") != "message":
            continue
        for content in item.get("content", []):
            if not isinstance(content, dict):
                continue
            if content.get("type") == "output_text" and content.get("text"):
                parts.append(str(content["text"]))
            elif content.get("type") == "refusal" and content.get("refusal"):
                parts.append(str(content["refusal"]))
    # Bazı test/uyumluluk katmanları SDK kolaylık alanını taşıyabilir.
    if not parts and isinstance(data.get("output_text"), str):
        parts.append(data["output_text"])
    return "".join(parts).strip()

def parse_provider_response(data, config):
    if config["protocol"] == "anthropic_messages":
        return "".join(
            block.get("text", "") for block in data.get("content", [])
            if isinstance(block, dict) and block.get("type") == "text").strip()
    if config["protocol"] == "openai_responses":
        return openai_response_text(data)
    return ((data.get("choices") or [{}])[0].get("message") or {}).get(
        "content", "").strip()

def provider_completion_limit_reason(data, config):
    """Return a provider-specific truncation reason, otherwise an empty str."""
    if not isinstance(data, dict):
        return ""
    if config["protocol"] == "anthropic_messages":
        reason = str(data.get("stop_reason") or "").strip().lower()
        return reason if reason in ("max_tokens", "model_context_window_exceeded") else ""
    if config["protocol"] == "openai_responses":
        if str(data.get("status") or "").strip().lower() != "incomplete":
            return ""
        details = data.get("incomplete_details") or {}
        return str(details.get("reason") or "incomplete").strip().lower()
    choice = (data.get("choices") or [{}])[0]
    reason = str(
        (choice.get("finish_reason") or "")
        if isinstance(choice, dict) else ""
    ).strip().lower()
    return reason if reason in (
        "length", "max_tokens", "model_length", "context_length") else ""

def iter_sse_events(response):
    event_name, data_lines = "", []
    for raw in response:
        try:
            line = raw.decode("utf-8").rstrip("\r\n")
        except UnicodeDecodeError:
            continue
        if not line:
            if data_lines:
                yield event_name, "\n".join(data_lines)
            event_name, data_lines = "", []
        elif line.startswith(":"):
            continue
        elif line.startswith("event:"):
            event_name = line[6:].strip()
        elif line.startswith("data:"):
            data_lines.append(line[5:].lstrip())
    if data_lines:
        yield event_name, "\n".join(data_lines)

def provider_stream_delta(event_name, raw_data, config):
    if raw_data == "[DONE]":
        return "done", ""
    try:
        data = json.loads(raw_data)
    except (TypeError, ValueError):
        return "ignore", ""
    if event_name == "error" or data.get("type") == "error":
        return "error", "Model sağlayıcısı akışı tamamlayamadı."
    if config["protocol"] == "anthropic_messages":
        if data.get("type") == "message_delta":
            reason = str(
                (data.get("delta") or {}).get("stop_reason") or ""
            ).strip().lower()
            if reason in ("max_tokens", "model_context_window_exceeded"):
                return (
                    "incomplete",
                    "Yanıt seçili çıktı sınırına ulaştığı için yarım kaldı.")
            if reason:
                return "done", ""
        if data.get("type") == "message_stop":
            return "done", ""
        if data.get("type") != "content_block_delta":
            return "ignore", ""
        delta = data.get("delta") or {}
        if delta.get("type") == "text_delta" and delta.get("text"):
            return "text", delta["text"]
        if delta.get("type") == "thinking_delta":
            return "thinking", ""
        return "ignore", ""
    if config["protocol"] == "openai_responses":
        event_type = data.get("type") or event_name
        if event_type == "response.completed":
            return "done", ""
        if event_type == "response.incomplete":
            return "incomplete", "OpenAI yanıtı tamamlanmadan kesildi."
        if event_type == "response.failed":
            return "error", "OpenAI yanıtı tamamlanamadı."
        if event_type == "response.output_text.delta" and data.get("delta"):
            return "text", data["delta"]
        if event_type == "response.refusal.delta" and data.get("delta"):
            return "text", data["delta"]
        if event_type in (
                "response.reasoning_text.delta",
                "response.reasoning_summary_text.delta"):
            return "thinking", ""
        return "ignore", ""
    choice = (data.get("choices") or [{}])[0]
    finish_reason = str(
        (choice.get("finish_reason") or "")
        if isinstance(choice, dict) else ""
    ).strip().lower()
    if finish_reason in (
            "length", "max_tokens", "model_length", "context_length"):
        return (
            "incomplete",
            "Yanıt seçili çıktı sınırına ulaştığı için yarım kaldı.")
    if finish_reason and finish_reason not in ("stop", "eos", "end_turn"):
        return "error", "Model sağlayıcısı yanıtı güvenle tamamlayamadı."
    if finish_reason:
        return "done", ""
    delta = choice.get("delta") if isinstance(choice, dict) else {}
    delta = delta or {}
    if delta.get("content"):
        return "text", delta["content"]
    if delta.get("reasoning_content") or delta.get("reasoning"):
        return "thinking", ""
    return "ignore", ""

def _ds_complete_once(messages, max_tokens, provider_id, model_id, timeout):
    """Tek bir akışsız model çağrısı; (metin, kesildi mi) döner."""
    request, config = provider_request(
        {"messages": messages, "max_tokens": max_tokens, "stream": False},
        provider_id=provider_id, model_id=model_id)
    timeout = (
        float(timeout) if timeout is not None
        else ARTIFACT_PROVIDER_TIMEOUT_SECONDS)
    with open_provider_url(
            request, config, timeout=timeout) as response:
        raw = read_limited(response, 16 * 1024 * 1024)
    try:
        data = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ProviderError(
            "provider_unreadable_response",
            "Model sağlayıcısının yanıtı okunamadı.")
    truncated = bool(provider_completion_limit_reason(data, config))
    try:
        text = parse_provider_response(data, config)
    except (KeyError, TypeError):
        raise ProviderError(
            "provider_unreadable_response",
            "Model sağlayıcısının yanıtı okunamadı.")
    return text, truncated

def ds_complete(messages, max_tokens=MAX_TOKENS_NOTE,
                provider_id=None, model_id=None, timeout=None):
    """Streamsiz yanıt; verilirse durable sağlayıcı/model pinini kullanır."""
    text, truncated = _ds_complete_once(
        messages, max_tokens, provider_id, model_id, timeout)
    if truncated:
        raise ProviderError(
            "provider_output_truncated",
            "Model yanıtı çıktı sınırına ulaştığı için yarım kaldı. "
            "Daha büyük bir bağlam penceresi seçip yeniden deneyin.")
    return text

def ds_complete_continued(messages, max_tokens=8000, max_chunks=2,
                          provider_id=None, model_id=None, timeout=None):
    """Çıktı sınırına takılan yanıtları kaldığı yerden sürdürür.

    Düşük çıktı sınırı olan veya reasoning bütçesini aynı limitten harcayan
    modeller uzun ikincil kayıtları (özet, mektup, seans notu) tek parçada
    bitiremez. Kesilen yanıtın kısmi metni asistan mesajı olarak geri verilir
    ve modelden devam etmesi istenir; bu, parça bütçesi dolana dek yinelenir.
    Bütçe dolsa bile eldeki metin döndürülür: kullanıcı onayına sunulan
    taslaklar eksik kalmaktansa görünür olsun.
    """
    working = [dict(message) for message in messages]
    parts = []
    for _ in range(max(1, max_chunks)):
        text, truncated = _ds_complete_once(
            working, max_tokens, provider_id, model_id, timeout)
        if text:
            parts.append(text)
        if not truncated:
            return "\n".join(parts)
        working.append({"role": "assistant", "content": text})
        working.append({"role": "user", "content":
                        "Yazmaya tam kaldığın yerden devam et. Yalnız kalan "
                        "kısmı yaz; baştan başlama, özetleme, açıklama ekleme."})
    return "\n".join(parts)

def _artifact_provider_pin(provider_id=None, model_id=None,
                           pin_resolver=None):
    """Resolve a lazy durable pin only when an artifact needs the model."""
    if pin_resolver is not None:
        provider_id, model_id = pin_resolver(provider_id, model_id)
    kwargs = {}
    if provider_id is not None:
        kwargs["provider_id"] = provider_id
    if model_id is not None:
        kwargs["model_id"] = model_id
    return kwargs

