            # yapılmaz.
            recover_stale_chat_requests_for_status()
            query = self.query()
            request_id = (query.get("request_id") or "").strip()
            conv_id = query.get("conv_id")
            with db() as c:
                if request_id:
                    try:
                        request_id = clean_chat_request_id(request_id)
                    except RequestInputError as exc:
                        self.send_json({"error": str(exc)}, exc.status)
                        return
                    row = chat_request_row(request_id, c)
                else:
                    try:
                        conv_id = int(conv_id or 0)
                    except (TypeError, ValueError):
                        conv_id = 0
                    if not conv_id:
                        self.send_json(
                            {"error": "mesaj isteği belirtilmedi"}, 400)
                        return
                    row = latest_chat_request_for_conv(conv_id, c)
            if not row:
                self.send_json({"error": "mesaj isteği bulunamadı"}, 404)
